package com.orderflow.inventory;
import com.orderflow.contracts.Events.*;import jakarta.persistence.*;import jakarta.validation.constraints.Min;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.UUID;import java.util.List;import java.util.Objects;
@SpringBootApplication public class InventoryApplication{public static void main(String[]a){SpringApplication.run(InventoryApplication.class,a);}@Bean Jackson2JsonMessageConverter json(){return new Jackson2JsonMessageConverter();}@Bean TopicExchange events(){return new TopicExchange("orderflow.events",true,false);}@Bean TopicExchange deadLetters(){return new TopicExchange("orderflow.dlx",true,false);}@Bean Queue inventoryDeadLetter(){return QueueBuilder.durable("inventory.dead-letter").build();}@Bean Binding inventoryDlq(Queue inventoryDeadLetter,TopicExchange deadLetters){return BindingBuilder.bind(inventoryDeadLetter).to(deadLetters).with("#");}@Bean Queue orders(){return QueueBuilder.durable("inventory.order-created").deadLetterExchange("orderflow.dlx").build();}@Bean Queue cancelled(){return QueueBuilder.durable("inventory.order-cancelled").deadLetterExchange("orderflow.dlx").build();}@Bean Binding b1(Queue orders,TopicExchange events){return BindingBuilder.bind(orders).to(events).with("order.created");}@Bean Binding b2(Queue cancelled,TopicExchange events){return BindingBuilder.bind(cancelled).to(events).with("order.cancelled");}}
@Entity @Table(name="inventory",schema="inventory")class Stock{@Id@Column(name="product_id")UUID productId;int available,reserved;@Version long version;protected Stock(){}Stock(UUID p,int n){productId=p;available=n;}}
@Entity @Table(name="reservations",schema="inventory")@IdClass(ReservationId.class)class Reservation{@Id@Column(name="order_id")UUID orderId;@Id@Column(name="product_id")UUID productId;int quantity;String status;protected Reservation(){}Reservation(UUID o,UUID p,int q){orderId=o;productId=p;quantity=q;status="RESERVED";}}class ReservationId implements java.io.Serializable{UUID orderId,productId;public ReservationId(){}public boolean equals(Object o){return o instanceof ReservationId r&&Objects.equals(orderId,r.orderId)&&Objects.equals(productId,r.productId);}public int hashCode(){return Objects.hash(orderId,productId);}}
@Entity @Table(name="processed_events",schema="inventory")class Seen{@Id@Column(name="event_id")UUID id;@Column(name="processed_at")Instant at=Instant.now();protected Seen(){}Seen(UUID i){id=i;}}
interface StockRepo extends JpaRepository<Stock,UUID>{@Modifying@org.springframework.data.jpa.repository.Query("update Stock s set s.available=s.available-:q,s.reserved=s.reserved+:q where s.productId=:p and s.available>=:q")int reserve(@Param("p")UUID p,@Param("q")int q);@Modifying@org.springframework.data.jpa.repository.Query("update Stock s set s.available=s.available+:q,s.reserved=s.reserved-:q where s.productId=:p and s.reserved>=:q")int release(@Param("p")UUID p,@Param("q")int q);}interface ReservationRepo extends JpaRepository<Reservation,ReservationId>{List<Reservation>findByOrderIdAndStatus(UUID o,String s);}interface SeenRepo extends JpaRepository<Seen,UUID>{}
@Service class InventoryService{private final StockRepo stock;private final ReservationRepo reservations;private final SeenRepo seen;private final RabbitTemplate rabbit;InventoryService(StockRepo s,ReservationRepo r,SeenRepo e,RabbitTemplate t){stock=s;reservations=r;seen=e;rabbit=t;}@Transactional @RabbitListener(queues="inventory.order-created")public void reserve(OrderCreated e){if(seen.existsById(e.eventId()))return;try{for(var l:e.items()){if(stock.reserve(l.productId(),l.quantity())!=1)throw new IllegalStateException("insufficient stock for "+l.productId());reservations.save(new Reservation(e.orderId(),l.productId(),l.quantity()));}seen.save(new Seen(e.eventId()));rabbit.convertAndSend("orderflow.events","inventory.reserved",new InventoryReserved(UUID.randomUUID(),e.orderId(),e.total(),Instant.now()));}catch(Exception x){release(e.orderId());seen.save(new Seen(e.eventId()));rabbit.convertAndSend("orderflow.events","inventory.failed",new InventoryReservationFailed(UUID.randomUUID(),e.orderId(),x.getMessage(),Instant.now()));}}@Transactional @RabbitListener(queues="inventory.order-cancelled")public void cancel(OrderCancelled e){if(seen.existsById(e.eventId()))return;release(e.orderId());seen.save(new Seen(e.eventId()));}void release(UUID order){for(var r:reservations.findByOrderIdAndStatus(order,"RESERVED")){stock.release(r.productId,r.quantity);r.status="RELEASED";}}@Transactional Stock set(UUID p,int q){return stock.save(new Stock(p,q));}}
@RestController@RequestMapping("/api/inventory")class InventoryController{private final InventoryService s;InventoryController(InventoryService s){this.s=s;}@PutMapping("/{id}")Stock set(@PathVariable UUID id,@RequestParam@Min(0)int quantity){return s.set(id,quantity);}}
